# Build-ExcelPasswordMatrix
# Module PowerShell - Generate Excel Matrix
# Version 1.0
# Author : FRXLAB

Function FRX_XL-RGB {
    [CmdletBinding(HelpUri = 'https://github.com/FRXLAB')]
    param($HexColor="328FB9")
    # IN  : 328FB9
    # OUT : 12160818
    $r = [Convert]::ToInt32($HexColor.Substring(0,2), 16)
    $g = [Convert]::ToInt32($HexColor.Substring(2,2), 16)
    $b = [Convert]::ToInt32($HexColor.Substring(4,2), 16)
    $xlcolor = $r + ($g * [math]::pow(2,8)) + ($b * [math]::pow(2,16))  #328FB9
    return $xlcolor 
}

function Build-ExcelPassMatrix{
    <#
    .Synopsis
       Script qui permet de générer des matrices sur EXCEL, 
       Le prérequis obligatoire est d'avoir un composant COM excel présent sur la machine
    .DESCRIPTION
       Script qui permet de générer des matrices sur EXCEL, 
       Le prérequis obligatoire est d'avoir un composant COM excel présent sur la machine
    .EXAMPLE
       Build-ExcelPassMatrix "Albert Lingot"
       par défaut la liste sera basé sur de l'Alphanumérique (type user)
    .EXAMPLE
        Build-ExcelPassMatrix -Username "Gérard Manvuca" -usertype admin 
        Le type admin ajoute des caractères spéciaux dans la liste
    #>
    [CmdletBinding(HelpUri = 'https://github.com/FRXLAB')]
    param($Username="FRX",[ValidateSet("user", "admin")]$usertype="user")

    if($usertype -eq "admin"){$liste = 65..90 + 97..122 +48..57 +33+91..96}
    else                     {$liste = $liste = 65..90 + 97..122  }
    $listeChar = ""
    for ($i = 1; $i -le (4*10*13); $i++){ 
        $listechar += [char](get-random -InputObject $liste)
    }
    $groupSize = 3 ; $columns = 10 ; $rows = 13
    $groups = $listeChar -split "(.{${groupSize}})" | Where-Object {$_ -ne ""}

    $excelApp = New-Object -ComObject "Excel.application"
    $excelApp.visible = $true
    $classeur  = $excelApp.workbooks.add()
    $feuille = $classeur.worksheets.item(1)
    $feuille.name = "MatricePass"
    ("ABCDEFGHIJ").tochararray()| Foreach-Object {$col=2}{
        $feuille.cells.item(2,$col++) =[string]$_
        $feuille.cells.item($col,1) = ($col-2)
    }
        $feuille.cells.item($col+1,1) = ($col-1)

    # Afficher en format tableau
    for ($row = 2; $row -lt $rows; $row++) {
        for ($col = 1; $col -le $columns; $col++) {
            $index = ($row * $columns) + $col
            $cell = $groups[$index]
            $feuille.cells.item($row+1,$col+1) = $cell
            # Format d'affichage avec tabulation
            Write-Host ("{0,-4}" -f $cell) -NoNewline
        }
        Write-Host ""
    }

    $feuille.Range("A:K").ColumnWidth  = 5
    $feuille.cells.item(1,1) = "Matrice de : "
    $feuille.cells.item(1,1).font.bold=$true
    $feuille.cells.Range("A1:K1").font.size=18
    if($username.Length -gt 15){$username = $Username.substring(0,15)}
    $feuille.cells.item(1,4) = $Username
    
    $base64String = ""
    $tempImagePath = "$env:TEMP\monImage.png"
    [System.IO.File]::WriteAllBytes($tempImagePath, [Convert]::FromBase64String($base64String))
    $classeur = $feuille # 
    $shape = $classeur.Shapes.AddPicture($tempImagePath,$false,$true,277.75,0,43.25,24.79866)

    Remove-Item $tempImagePath

    $range = $feuille.Range("A2:K13")
    $range.Borders.LineStyle = 1 # xlContinuous
    $range.Borders.Weight    = 2 # xlThin

    $feuille.Range("A2:K2" ).interior.Color = FRX_XL-RGB -HexColor "328FB9"
    $feuille.Range("A2:A13").interior.Color = FRX_XL-RGB -HexColor "328FB9"

}
Export-ModuleMember -function Build-ExcelPassMatrix,FRX_XL-RGB
